// Agregar resultados de todas as verificações
const healthApi = $('Health Check API').item.json;
const metrics = $('Verificar Métricas').item.json;
const frontend = $('Frontend Check').item.json;

const timestamp = new Date().toISOString();

// Analisar status da API
const apiStatus = {
  status: healthApi.statusCode === 200 ? 'healthy' : 'unhealthy',
  statusCode: healthApi.statusCode,
  response: healthApi.body || healthApi.data || {},
  timestamp: timestamp
};

// Analisar métricas
let metricsData = {};
if (metrics.statusCode === 200) {
  const metricsText = typeof metrics.body === 'string' ? metrics.body : JSON.stringify(metrics.body);
  // Extrair métricas importantes
  const httpRequestsMatch = metricsText.match(/http_requests_total\{.*?\} (\d+)/g);
  const httpDurationMatch = metricsText.match(/http_request_duration_seconds_bucket\{.*?\} ([\d.]+)/g);

  metricsData = {
    status: 'available',
    hasData: true,
    raw: metricsText.substring(0, 1000) // Primeiros 1000 caracteres
  };
} else {
  metricsData = {
    status: 'unavailable',
    hasData: false
  };
}

// Analisar frontend
const frontendStatus = {
  status: frontend.statusCode === 200 ? 'healthy' : 'unhealthy',
  statusCode: frontend.statusCode,
  timestamp: timestamp
};

// Determinar se há problemas
const issues = [];
if (apiStatus.status === 'unhealthy') {
  issues.push({
    type: 'api',
    severity: 'critical',
    message: `API retornou status ${apiStatus.statusCode}`,
    component: 'backend'
  });
}

if (metricsData.status === 'unavailable') {
  issues.push({
    type: 'metrics',
    severity: 'warning',
    message: 'Métricas não estão disponíveis',
    component: 'monitoring'
  });
}

if (frontendStatus.status === 'unhealthy') {
  issues.push({
    type: 'frontend',
    severity: 'critical',
    message: `Frontend retornou status ${frontendStatus.statusCode}`,
    component: 'frontend'
  });
}

return [{
  json: {
    timestamp: timestamp,
    api: apiStatus,
    metrics: metricsData,
    frontend: frontendStatus,
    issues: issues,
    hasIssues: issues.length > 0,
    issueCount: issues.length
  }
}];

// Separar problemas por tipo para análise especializada
const data = $input.item.json;
const issues = data.issues || [];

const infraIssues = issues.filter(i => 
  i.type === 'api' || 
  i.component === 'backend' || 
  i.component === 'monitoring'
);

const devIssues = issues.filter(i => 
  i.type === 'frontend' || 
  (i.type === 'api' && i.message.includes('code') || i.message.includes('error'))
);

const results = [];

// Se houver problemas de infra
if (infraIssues.length > 0) {
  results.push({
    json: {
      specialist: 'infra',
      issues: infraIssues,
      context: {
        api: data.api,
        metrics: data.metrics,
        timestamp: data.timestamp
      },
      requiresAnalysis: true
    }
  });
}

// Se houver problemas de desenvolvimento
if (devIssues.length > 0) {
  results.push({
    json: {
      specialist: 'developer',
      issues: devIssues,
      context: {
        frontend: data.frontend,
        api: data.api,
        timestamp: data.timestamp
      },
      requiresAnalysis: true
    }
  });
}

// Se não houver problemas específicos mas houver algum problema geral
if (results.length === 0 && issues.length > 0) {
  results.push({
    json: {
      specialist: 'infra',
      issues: issues,
      context: data,
      requiresAnalysis: true
    }
  });
}

return results.length > 0 ? results : [{ json: { skip: true, message: 'Nenhum problema detectado' } }];

// Preparar prompt para Claude AI
const data = $input.item.json;
const promptTemplate = $env.PROMPT_INFRA_SPECIALIST || '';

// Substituir placeholders no prompt
let prompt = promptTemplate
  .replace(/\{\{issues\}\}/g, JSON.stringify(data.issues, null, 2))
  .replace(/\{\{context\}\}/g, JSON.stringify(data.context, null, 2));

return [{
  json: {
    ...data,
    prompt: prompt,
    model: $env.LLM_MODEL || 'claude-3-5-sonnet-20241022'
  }
}];

