// Processar resposta do LLM e extrair diagnóstico e plano de ação
const llmResponse = $input.item.json;

// Determinar qual especialista chamou (infra ou dev)
let originalData;
try {
  originalData = $('Rotear para Especialistas').item.json;
} catch (e) {
  // Se não conseguir, tentar pegar do nó anterior
  try {
    originalData = $('Preparar Prompt Infra').item.json;
  } catch (e2) {
    originalData = $('Preparar Prompt Dev').item.json;
  }
}

// Extrair texto da resposta do LLM (formato Anthropic API via HTTP Request)
let analysisText = '';

// HTTP Request retorna body como string ou objeto
let responseBody = llmResponse.body || llmResponse;
if (typeof responseBody === 'string') {
  try {
    responseBody = JSON.parse(responseBody);
  } catch (e) {
    responseBody = { content: [{ type: 'text', text: responseBody }] };
  }
}

// Extrair conteúdo da resposta Anthropic
if (responseBody.content && Array.isArray(responseBody.content)) {
  const textContent = responseBody.content.find(c => c.type === 'text');
  analysisText = textContent ? textContent.text : JSON.stringify(responseBody.content);
} else if (responseBody.text) {
  analysisText = responseBody.text;
} else if (responseBody.message) {
  analysisText = responseBody.message.content || responseBody.message;
} else {
  analysisText = JSON.stringify(responseBody);
}

// Tentar extrair JSON estruturado se presente
let diagnosis = {};
let actionPlan = [];
let requiresApproval = false;
let severity = 'medium';

try {
  // Tentar encontrar JSON na resposta
  const jsonMatch = analysisText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    const parsed = JSON.parse(jsonMatch[0]);
    diagnosis = parsed.diagnosis || parsed.analysis || {};
    actionPlan = parsed.actionPlan || parsed.actions || [];
    requiresApproval = parsed.requiresApproval !== false;
    severity = parsed.severity || severity;
  } else {
    // Se não houver JSON, criar estrutura a partir do texto
    diagnosis = {
      summary: analysisText.substring(0, 500),
      rootCause: 'A ser determinado pela análise completa',
      impact: 'Médio'
    };

    // Extrair ações do texto
    const actionMatches = analysisText.match(/\d+\.\s*([^\n]+)/g);
    if (actionMatches) {
      actionPlan = actionMatches.map((match, idx) => ({
        id: idx + 1,
        description: match.replace(/^\d+\.\s*/, ''),
        type: 'manual',
        requiresApproval: true
      }));
    }

    requiresApproval = true;
  }
} catch (e) {
  // Se falhar, usar texto completo
  diagnosis = {
    summary: analysisText,
    error: 'Não foi possível parsear resposta estruturada'
  };
  actionPlan = [{
    id: 1,
    description: 'Revisar análise manualmente',
    type: 'manual',
    requiresApproval: true
  }];
}

// Determinar se há ações que requerem execução
const executableActions = actionPlan.filter(a => 
  a.type === 'automated' || 
  a.type === 'script' || 
  (a.commands && a.commands.length > 0)
);

return [{
  json: {
    specialist: originalData.specialist,
    timestamp: new Date().toISOString(),
    issues: originalData.issues,
    diagnosis: diagnosis,
    actionPlan: actionPlan,
    executableActions: executableActions,
    requiresApproval: requiresApproval || executableActions.length > 0,
    severity: severity,
    rawAnalysis: analysisText.substring(0, 2000), // Limitar tamanho
    context: originalData.context
  }
}];

// Formatar mensagem para aprovação
const report = $input.item.json;
const savedReport = $('Salvar Relatório').item.json;

const severityEmoji = {
  'critical': '🔴',
  'high': '🟠',
  'medium': '🟡',
  'low': '🟢'
}[report.severity] || '⚪';

let message = `${severityEmoji} *ALERTA: Problema Detectado no CredGestor*\n\n`;
message += `*Especialista:* ${report.specialist === 'infra' ? 'Infraestrutura' : 'Desenvolvimento'}\n`;
message += `*Severidade:* ${report.severity.toUpperCase()}\n`;
message += `*Data/Hora:* ${new Date(report.timestamp).toLocaleString('pt-BR')}\n\n`;

message += `*📋 PROBLEMAS DETECTADOS:*\n`;
for (const issue of report.issues) {
  message += `• ${issue.type}: ${issue.message}\n`;
}

message += `\n*🔍 DIAGNÓSTICO:*\n`;
if (report.diagnosis.summary) {
  message += `${report.diagnosis.summary.substring(0, 300)}...\n`;
}

message += `\n*📝 PLANO DE AÇÃO:*\n`;
for (let i = 0; i < Math.min(report.actionPlan.length, 5); i++) {
  const action = report.actionPlan[i];
  message += `${i + 1}. ${action.description}\n`;
}
if (report.actionPlan.length > 5) {
  message += `... e mais ${report.actionPlan.length - 5} ações\n`;
}

message += `\n*⚠️ AÇÕES REQUEREM APROVAÇÃO*\n`;
message += `ID do Relatório: ${savedReport.id || 'N/A'}\n\n`;

message += `*Para aprovar e executar:*\n`;
message += `Responda: APROVAR ${savedReport.id || 'REPORT_ID'}\n\n`;
message += `*Para rejeitar:*\n`;
message += `Responda: REJEITAR ${savedReport.id || 'REPORT_ID'}\n`;

return [{
  json: {
    message: message,
    reportId: savedReport.id,
    report: report,
    channel: '#credgestor-alerts',
    thread_ts: null
  }
}];

// Resumo final da execução
const report = $('Processar Análise').item.json;
const savedReport = $('Salvar Relatório').item.json;

return [{
  json: {
    executionTime: new Date().toISOString(),
    reportId: savedReport.id,
    specialist: report.specialist,
    issuesFound: report.issues.length,
    severity: report.severity,
    actionsGenerated: report.actionPlan.length,
    requiresApproval: report.requiresApproval,
    status: 'completed'
  }
}];
